// 原Task保存集覆盖独立接触尾；真实历史生命从同World军事死因读，不借今日alive替代。
#include "task_shop_order_contact_world.hpp"
#include "task_shop_order_contact_control.hpp"
#include "resident/kernel/world_bundle.hpp"
#include "resident/kernel/private_shop_integration.hpp"
#include "resident/domains/military/military_roster_history.hpp"
namespace hanmo::resident {namespace {
const TaskShopOrderContactState* state(const WorldBundle& w){return w.tasks.shop_orders&&w.tasks.shop_orders->contacts?&*w.tasks.shop_orders->contacts:nullptr;}
Status ready(const WorldBundle& w){if(!w.catalog->task_shop_order_contacts_enabled||!w.task_shop_orders_enabled()||!w.private_shops_enabled()||!w.family_life_enabled()||!w.catalog->common||!w.catalog->interaction||!state(w))return common_failure("TaskShopOrderContactProfileRequired");return common_success();}
TaskShopOrderContactContext context(const WorldBundle& w,const PrivateShopOrderRead& orders,const DynamicStepInput* phase){return {w.common,w.tasks,*w.tasks.shop_orders,*state(w),*w.catalog->interaction,orders,phase,[&w,phase](const StableId& actor,Integer tick,const StableId& fact){FamilyDeathOriginRead deaths=[&w,phase](const StableId& who)->Outcome<std::optional<FamilyDeathOrigin>>{auto read=phase?query_military_actor_death(w.common,w.military,who,*phase):query_military_actor_death(w.common,w.military,who);if(!read.ok)return {false,{},read.error};if(!read.value)return {true,std::nullopt,{}};const auto& d=*read.value;return {true,FamilyDeathOrigin{d.actor_id,d.casualty_fact_id,d.battle_id,d.tick},{}};};return read_actor_presence_before_fact(w.common,*w.catalog->common,deaths,actor,tick,fact,phase);},w.dynamic_enabled()&&w.catalog->director&&w.catalog->director->dynamic_subjects?TaskShopOrderContactSubmitterMode::controlled_player:TaskShopOrderContactSubmitterMode::legacy_actor,[&w](Integer tick,const StableId& fact){return task_shop_order_contact_player_before(w.common,w.family,w.family_legacy_enabled()?&w.family_legacy:nullptr,tick,fact);}};}
}
Status validate_task_shop_order_contact_sources_world(const WorldBundle& w,const PrivateShopOrderRead& orders,const DynamicStepInput* phase){auto valid=validate_task_shop_order_contact_layout(w.common,w.catalog->identity.module_versions,w.catalog->task_shop_order_contacts_enabled,state(w));if(!valid.ok||!w.catalog->task_shop_order_contacts_enabled)return valid;valid=ready(w);if(!valid.ok)return valid;return validate_task_shop_order_contacts(context(w,orders,phase));}
Status validate_task_shop_order_contact_world(const WorldBundle& w){auto valid=validate_task_shop_order_contact_layout(w.common,w.catalog->identity.module_versions,w.catalog->task_shop_order_contacts_enabled,state(w));if(!valid.ok||!w.catalog->task_shop_order_contacts_enabled)return valid;valid=ready(w);if(!valid.ok)return valid;auto holder=PrivateShopWorldAccess::create(w);if(!holder.ok)return {false,{},holder.error};return validate_task_shop_order_contacts(context(w,holder.value->orders(),nullptr));}
Status record_task_shop_order_contact_world(WorldBundle& w,const PrivateShopOrderRead& orders,const StableId& action,const TaskShopOrderDeliveryQuote& quote){if(!w.catalog->task_shop_order_contacts_enabled)return state(w)?common_failure("TaskShopOrderContactProfileMismatch"):common_success();auto valid=ready(w);if(!valid.ok)return valid;auto result=record_task_shop_order_contact_in_candidate(w.common,*w.tasks.shop_orders->contacts,context(w,orders,nullptr),action,quote);return result.ok?common_success():Status{false,{},result.error};}
Outcome<StableId> task_shop_order_contact_new_result_world(const WorldBundle& before,const WorldBundle& after,const StableId& actor,const StableId& kind,const ReceiptDetails& details){if(!after.catalog->task_shop_order_contacts_enabled){if(before.catalog->task_shop_order_contacts_enabled||state(before)||state(after))return {false,{},common_failure("TaskShopOrderContactProfileMismatch").error};return {true,{}, {}};}auto valid=ready(before);if(!valid.ok)return {false,{},valid.error};valid=ready(after);if(!valid.ok)return {false,{},valid.error};return task_shop_order_contact_new_result_source(state(before),state(after),actor,kind,details,after.common.tick());}
Status bind_task_shop_order_contact_result_world(WorldBundle& w,const StableId& source,const StableId& actor,Integer request,const CommitResult& result){if(!w.catalog->task_shop_order_contacts_enabled)return source.empty()?common_success():common_failure("TaskShopOrderContactProfileRequired");auto valid=ready(w);if(!valid.ok)return valid;return bind_task_shop_order_contact_result(w.common,*w.tasks.shop_orders->contacts,source,actor,request,result);}
}
